import torch
import torch.nn.functional as F

def _fallback_grouped_mm(A, B, offsets=None):
    if offsets is None:
        if A.dim() == 3:
            return torch.bmm(A, B)
        return A @ B
    ends = offsets.to(device=A.device, dtype=torch.long).flatten()
    results = []
    start = 0
    for i in range(B.shape[0]):
        end = int(ends[i].item())
        results.append(A[start:end] @ B[i])
        start = end
    return torch.cat(results, dim=0)

def run(A, B, offsets=None):
    if hasattr(F, "grouped_mm"):
        return F.grouped_mm(A, B, offs=offsets)
    if hasattr(torch, "_grouped_mm"):
        return torch._grouped_mm(A, B, offs=offsets)
    return _fallback_grouped_mm(A, B, offsets)
